// Kiểm tra danh sách clip chờ đăng
const response = $input.first().json;
const items = response.items || [];

if (items.length === 0) {
  return [];
}

// Lấy clip đầu tiên trong hàng đợi để xử lý
const nextClip = items[0];

// Làm sạch tiêu đề không dính chữ Part
let cleanTitle = (nextClip.title || '').replace(/[\s\-_\(\[\{]+(part|phần|tập)\s*[\d]+[\)\]\}]*/gi, '').trim();

return [{
  json: {
    account_name: nextClip.account_name,
    channel: nextClip.channel,
    title: cleanTitle || nextClip.title,
    clip_key: nextClip.clip_key,
    part_label: nextClip.part_label || '',
    video_file: nextClip.video_file,
    hashtag_default: nextClip.hashtag || '#fyp #viral #trending',
    target_ip: nextClip.target_ip || 'US',
    adspower_id: nextClip.adspower_id
  }
}];

